/**
 * Retrieve high-scoring model answer for any IELTS, TOEFL, or PTE test.
 */
export function getSpeakingSampleAnswer(
  testSlug: string,
  promptIndex: number = 0,
  _fallbackPrompt?: string
): string | null {
  const answers = SPEAKING_SAMPLE_ANSWERS[testSlug];
  if (answers && answers.length > 0) {
    const index = promptIndex % answers.length;
    return answers[index] ?? null;
  }
  return null;
}
